-- Synthetic integration schema matching the existing Collections contract; no customer data.
create schema if not exists auth;
create schema if not exists private;
do $$begin if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated;end if;if not exists(select 1 from pg_roles where rolname='anon') then create role anon;end if;end$$;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table public.app_users(auth_user_id uuid primary key references auth.users,employee_name text,active boolean,perm_admin boolean,perm_collections boolean);
create function private.gp_is_admin() returns boolean language sql stable security definer set search_path='' as $$select coalesce((select active and perm_admin from public.app_users where auth_user_id=auth.uid()),false)$$;
create function private.gp_has_permission(text) returns boolean language sql stable security definer set search_path='' as $$select coalesce((select active and (perm_admin or perm_collections) from public.app_users where auth_user_id=auth.uid()),false)$$;
grant usage on schema public,private,auth to authenticated;
grant execute on function auth.uid(),private.gp_is_admin(),private.gp_has_permission(text) to authenticated;
create table if not exists public.collection_imports (
 id uuid primary key default gen_random_uuid(),
 source text not null check(source in ('mainstreet','qbo')),
 file_name text not null,
 report_as_of date,
 imported_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),
 completed_at timestamptz,
 status text not null default 'staging' check(status in ('staging','complete','failed')),
 row_count integer not null default 0
);
create index if not exists gp_collection_imports_source_time_idx on public.collection_imports(source,completed_at desc);

create table if not exists public.collection_source_rows (
 id bigint generated by default as identity primary key,
 import_id uuid not null references public.collection_imports(id) on delete cascade,
 source text not null check(source in ('mainstreet','qbo')),
 external_key text not null,
 case_key text,
 customer_name text not null,
 normalized_customer text not null,
 invoice_number text,
 transaction_type text not null,
 transaction_date date,
 due_date date,
 days_past_due integer,
 original_amount numeric(14,2) not null default 0,
 open_balance numeric(14,2) not null default 0,
 phone text,
 contact text,
 aging_bucket text,
 raw jsonb not null default '{}'::jsonb,
 constraint gp_collection_source_unique unique(import_id,external_key)
);
create index if not exists gp_collection_rows_import_type_idx on public.collection_source_rows(import_id,transaction_type);
create index if not exists gp_collection_rows_case_idx on public.collection_source_rows(case_key);

create table if not exists public.collection_cases (
 id uuid primary key default gen_random_uuid(),
 case_key text not null unique,
 customer_name text not null,
 normalized_customer text not null,
 invoice_number text,
 invoice_date date,
 due_date date,
 phone text,
 contact text,
 street_address text,
 city text,
 state_code text,
 zip_code text,
 last_purchase_text text,
 last_payment_text text,
 source_collection_notes text,
 edi_status text,
 edi_activity text,
 qbo_store_name text,
 mainstreet_import_id uuid references public.collection_imports(id),
 qbo_import_id uuid references public.collection_imports(id),
 mainstreet_balance numeric(14,2),
 qbo_balance numeric(14,2),
 mainstreet_aging text,
 qbo_days_past_due integer not null default 0,
 mainstreet_seen_at timestamptz,
 qbo_seen_at timestamptz,
 status text not null default 'open' check(status in ('open','contacted','promise','disputed','resolved_pending','reconciled')),
 assigned_to uuid references auth.users(id) on delete set null,
 next_follow_up date,
 resolved_at timestamptz,
 needs_mainstreet_update boolean not null default false,
 needs_qbo_update boolean not null default false,
 mainstreet_confirmed_at timestamptz,
 qbo_confirmed_at timestamptz,
 last_activity_at timestamptz,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create index if not exists gp_collection_cases_status_followup_idx on public.collection_cases(status,next_follow_up);
create index if not exists gp_collection_cases_assignee_idx on public.collection_cases(assigned_to);

create table if not exists public.collection_actions (
 id bigint generated by default as identity primary key,
 case_id uuid not null references public.collection_cases(id) on delete restrict,
 action_type text not null check(action_type in ('note','contacted','no_answer','left_voicemail','statement_sent','payment_claim','promise_broken','research','wrong_number','promise','disputed','rectified','reopen','confirm_mainstreet','confirm_qbo','assign')),
 note text not null default '',
 details jsonb not null default '{}'::jsonb,
 amount numeric(14,2),
 recorded_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),
 next_follow_up date,
 needs_mainstreet_update boolean,
 needs_qbo_update boolean
);
create index if not exists gp_collection_actions_case_date_idx on public.collection_actions(case_id,created_at desc);
create index if not exists gp_collection_actions_time_idx on public.collection_actions(created_at desc);


create table public.collection_account_notes(id bigint generated always as identity primary key,normalized_customer text,customer_name text,category text,subject text,note text,highlighted boolean default false,recorded_by uuid references auth.users,created_at timestamptz default now());
grant select,insert on public.collection_imports,public.collection_source_rows to authenticated;
grant select on public.collection_cases,public.collection_actions,public.collection_account_notes to authenticated;
grant usage,select on sequence public.collection_source_rows_id_seq to authenticated;
alter table public.collection_source_rows enable row level security;
create policy fixture_read_rows on public.collection_source_rows for select to authenticated using(private.gp_has_permission('collections'));
create table public.outstanding_quotes(quote_number bigint primary key,normalized_customer_name text,customer_name text not null,quote_date text,module text,phone text,has_cell boolean,subtotal numeric,tax numeric,total numeric,original_csr text,parts jsonb,status text,contact_attempts integer,call_data jsonb,admin_coaching_note text);
create table public.audit_logs(id bigint generated always as identity primary key,supervisor_name text,action_type text,details text);
